import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BNdm2jZV.js";const h=JSON.parse('{"title":"Store","description":"","frontmatter":{},"headers":[],"relativePath":"reference/store.md","filePath":"reference/store.md"}'),d={name:"reference/store.md"};function s(c,e,n,i,p,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="store" tabindex="-1">Store <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Store&quot;">​</a></h1><p>模板使用 Pinia 管理跨页面状态。业务代码从 <code>@/store</code> 导入相应的 Getters / Actions，读取引用用 <code>.value</code>，修改走动作。只属于一个组件或页面的状态可以继续用本地 ref。</p><table tabindex="0"><thead><tr><th>Store</th><th>访问入口</th><th>持久化</th></tr></thead><tbody><tr><td><a href="./store/setting.html">Setting</a></td><td><code>useSettingGetters</code> / <code>useSettingActions</code></td><td>Local Storage <code>piniaSettingStore</code>，排除锁屏设置弹窗显隐；当前语言另外保存。</td></tr><tr><td><a href="./store/navigation.html#menu-store">Menu</a></td><td><code>useMenuGetters</code> / <code>useMenuActions</code></td><td>Local Storage 保存当前菜单和折叠状态；标签列表另存 Session Storage。</td></tr><tr><td><a href="./store/navigation.html#keepalive-store">KeepAlive</a></td><td><code>useKeepAliveGetters</code> / <code>useKeepAliveActions</code></td><td>Session Storage 保存可缓存组件名。</td></tr><tr><td><a href="./store/runtime.html#runtime-store">Runtime</a></td><td><code>useRuntimeGetters</code> / <code>useRuntimeActions</code></td><td>无；随当前 Pinia 实例释放。</td></tr><tr><td><a href="./store/runtime.html#lock-screen-store">Lock Screen</a></td><td><code>useLockScreenGetters</code> / <code>useLockScreenActions</code></td><td>Local Storage 的历史布尔值，支持跨标签同步。</td></tr><tr><td><a href="./store/signing.html">Signing</a></td><td><code>useSigningGetters</code> / <code>useSigningActions</code></td><td>Local Storage 持久化账号显示信息，路由守卫另读 token。</td></tr></tbody></table><h2 id="初始化与扩展" tabindex="-1">初始化与扩展 <a class="header-anchor" href="#初始化与扩展" aria-label="Permalink to &quot;初始化与扩展&quot;">​</a></h2><p><code>setupStore(app)</code> 安装 Pinia 与持久化插件，应用卸载时释放 Pinia 实例及作用域。模板入口已调用，业务代码无需再次注册。Menu 与 Signing 依赖 Router 注入，请在应用组件的有效 setup 中访问。</p><p>新增 Store 在 <code>apps/admin/src/store/modules</code> 按领域建目录并指定唯一 ID。需要持久化时使用 <code>pick</code> 或 <code>omit</code>，选定存储范围和稳定的 key，只保存可序列化的值。调用接口放到 <code>apps/admin/src/store/hooks</code>，再由 <code>apps/admin/src/store/index.ts</code> 导出。原始 <code>pinia…Store</code> 同样公开给模板内部，但页面使用 hooks 可以减少对实现字段的直接依赖。</p><p>缓存键和 JSON 结构是已有数据契约。换 key、拆字段或改变序列化格式时，要考虑旧数据的读取、迁移和回退。浏览器缓存不应保存服务端密钥。</p><p><a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/8e8fe5ee7a0260930399cf1af49813f601b1e2b1/apps/admin/src/store/index.ts" target="_blank" rel="noreferrer">初始化与公开导出</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/8e8fe5ee7a0260930399cf1af49813f601b1e2b1/apps/admin/src/store/README.md" target="_blank" rel="noreferrer">Store 源码约定</a></p>',8)])])}const m=t(d,[["render",s]]);export{h as __pageData,m as default};
